output.content:
import { createWorkflowChain, andThen } from "@voltagent/core";
import { z } from "zod";

const workflow = createWorkflowChain({
  id: "math-operations",
  input: z.object({
    value: z.number(),
    operation: z.string(),
  }),
})
.andWhen({
  id: "check-double",
  condition: async ({ data }) => data.operation === 'double',
  step: andThen({
    id: "double",
    execute: async ({ data }) => ({
      result: data.value * 2,
    }),
  }),
})
.andWhen({
  id: "check-square",
  condition: async ({ data }) => data.operation === 'square',
  step: andThen({
    id: "square",
    execute: async ({ data }) => ({
      result: data.value * data.value,
    }),
  }),
});

export default workflow;

